import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第三册：培养技能 · 综合复习与自测 · 第36–47课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第三册：培养技能 · 综合复习与自测 · 第36–47课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-3/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 综合复习与自测 · 第24–35课","link":"/life/english/new-concept/book-3/review-part-03"},"next":{"text":"第三册：培养技能 · 综合复习与自测 · 第48–58课","link":"/life/english/new-concept/book-3/review-part-05"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 综合复习与自测 · 第24–35课","link":"/life/english/new-concept/book-3/review-part-03"},"next":{"text":"第三册：培养技能 · 综合复习与自测 · 第48–58课","link":"/life/english/new-concept/book-3/review-part-05"}},"headers":[],"relativePath":"life/english/new-concept/book-3/review-part-04.md","filePath":"life/english/new-concept/book-3/review-part-04.md"}'),r={name:"life/english/new-concept/book-3/review-part-04.md"};function n(l,e,i,h,p,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-综合复习与自测-·-第36–47课" tabindex="-1">第三册：培养技能 · 综合复习与自测 · 第36–47课 <a class="header-anchor" href="#第三册-培养技能-·-综合复习与自测-·-第36–47课" aria-label="Permalink to &quot;第三册：培养技能 · 综合复习与自测 · 第36–47课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-36-·-so-与-such-的结果结构" tabindex="-1">Lesson 36 · so 与 such 的结果结构 <a class="header-anchor" href="#lesson-36-·-so-与-such-的结果结构" aria-label="Permalink to &quot;Lesson 36 · so 与 such 的结果结构 {#lesson-36-·-so-与-such-的结果结构}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> It was such an unexpected meeting that neither of us spoke for a moment.</p><h3 id="练习-1-35" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-35" aria-label="Permalink to &quot;练习 1 {#练习-1-35}&quot;">​</a></h3><p>填空：There were ___ many similarities that we laughed.（so/such）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> so</p><p><strong>解析：</strong> many 的数量结构用 so many。</p></details><p><strong>表达迁移：</strong> 写三句巧合经历，不编造具体概率。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I found my former classmate in a tiny bookshop abroad. We had both come to buy the same dictionary. It was such a surprising coincidence that we forgot to ask the price.</p><p>细节说明惊讶原因，未将罕见感受包装成数学概率。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-036">回看本课</a></p><h2 id="lesson-37-·-by、until-与时刻表现在时" tabindex="-1">Lesson 37 · by、until 与时刻表现在时 <a class="header-anchor" href="#lesson-37-·-by、until-与时刻表现在时" aria-label="Permalink to &quot;Lesson 37 · by、until 与时刻表现在时 {#lesson-37-·-by、until-与时刻表现在时}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We must reach the platform by six, although the train does not leave until ten past.</p><h3 id="练习-1-36" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-36" aria-label="Permalink to &quot;练习 1 {#练习-1-36}&quot;">​</a></h3><p>例句最迟几点到站台？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 六点。</p><p><strong>解析：</strong> by six 表示截止时间。</p></details><p><strong>表达迁移：</strong> 写三句赶车计划，区分列车时间、个人截止点和等候时间。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The train leaves at 7:20. We should reach the station by seven. If the platform is closed, we will wait in the hall until it opens.</p><p>三个时间表达分别控制离站、到达和等候，行为安排清楚。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-037">回看本课</a></p><h2 id="lesson-38-·-目的不定式与-for-doing" tabindex="-1">Lesson 38 · 目的不定式与 for doing <a class="header-anchor" href="#lesson-38-·-目的不定式与-for-doing" aria-label="Permalink to &quot;Lesson 38 · 目的不定式与 for doing {#lesson-38-·-目的不定式与-for-doing}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The group marked a stone each evening to keep track of passing days.</p><h3 id="练习-1-37" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-37" aria-label="Permalink to &quot;练习 1 {#练习-1-37}&quot;">​</a></h3><p>例句的目的部分从哪个词开始？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> to keep track of ... 说明标记的目的。</p></details><p><strong>表达迁移：</strong> 设计一种虚构的简单记录法，用三句说明材料、操作和限制。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We place one bead in a jar to mark each day. A red bead marks the start of a new week. The system fails if someone forgets to add a bead.</p><p>目的清楚，规则可操作，并指出依赖持续执行这一限制。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-038">回看本课</a></p><h2 id="lesson-39-·-不定式后置修饰与介词" tabindex="-1">Lesson 39 · 不定式后置修饰与介词 <a class="header-anchor" href="#lesson-39-·-不定式后置修饰与介词" aria-label="Permalink to &quot;Lesson 39 · 不定式后置修饰与介词 {#lesson-39-·-不定式后置修饰与介词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We had a reliable guide to consult and a marked path to follow.</p><h3 id="练习-1-38" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-38" aria-label="Permalink to &quot;练习 1 {#练习-1-38}&quot;">​</a></h3><p>补全：There is nothing to worry ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> about</p><p><strong>解析：</strong> worry about 的介词保留。</p></details><p><strong>表达迁移：</strong> 用三句向旅伴说明一次徒步准备，既给依据也保留注意事项。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We have a clear map to follow. The ranger has checked the lower trail this morning. We should still watch for loose stones after the rain.</p><p>安慰建立在地图与检查上，最后一句避免把已有准备等同于零风险。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-039">回看本课</a></p><h2 id="lesson-40-·-反身代词与相互代词" tabindex="-1">Lesson 40 · 反身代词与相互代词 <a class="header-anchor" href="#lesson-40-·-反身代词与相互代词" aria-label="Permalink to &quot;Lesson 40 · 反身代词与相互代词 {#lesson-40-·-反身代词与相互代词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The two actors introduced themselves before they introduced each other to the director.</p><h3 id="练习-1-39" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-39" aria-label="Permalink to &quot;练习 1 {#练习-1-39}&quot;">​</a></h3><p>例句的 themselves 指谁？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 两位演员各自本人。</p><p><strong>解析：</strong> 反身代词回指主语成员。</p></details><p><strong>表达迁移：</strong> 写三句说明一次角色排练，明确谁介绍谁以及谁独自准备。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Nina introduced herself as the host. She then introduced Omar to the audience. Omar had prepared the entire demonstration by himself.</p><p>人名和代词交替使用但指向清楚，by himself 补充独立准备的信息。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-040">回看本课</a></p><h2 id="lesson-41-·-while-与-whereas-的对照" tabindex="-1">Lesson 41 · while 与 whereas 的对照 <a class="header-anchor" href="#lesson-41-·-while-与-whereas-的对照" aria-label="Permalink to &quot;Lesson 41 · while 与 whereas 的对照 {#lesson-41-·-while-与-whereas-的对照}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The village is quiet after sunset, whereas the market town remains busy until midnight.</p><h3 id="练习-1-40" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-40" aria-label="Permalink to &quot;练习 1 {#练习-1-40}&quot;">​</a></h3><p>例句比较的是交通还是夜间活动？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 夜间活动。</p><p><strong>解析：</strong> quiet after sunset 与 busy until midnight 是对应信息。</p></details><p><strong>表达迁移：</strong> 比较两种居住环境，用三句写出同一维度的差异与个人取舍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The city flat is close to work, whereas the cottage requires a long drive. The cottage offers more outdoor space. For now, a shorter commute matters more to me.</p><p>先比较通勤，再补充空间，最后说明个人权重而非普遍优劣。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-041">回看本课</a></p><h2 id="lesson-42-·-独立主格的独立主语" tabindex="-1">Lesson 42 · 独立主格的独立主语 <a class="header-anchor" href="#lesson-42-·-独立主格的独立主语" aria-label="Permalink to &quot;Lesson 42 · 独立主格的独立主语 {#lesson-42-·-独立主格的独立主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The main passage blocked, the team returned to the entrance.</p><h3 id="练习-1-41" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-41" aria-label="Permalink to &quot;练习 1 {#练习-1-41}&quot;">​</a></h3><p>把例句改为 because 从句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Because the main passage was blocked, the team returned to the entrance.</p><p><strong>解析：</strong> 恢复明确主语和限定谓语。</p></details><p><strong>表达迁移：</strong> 用三句写虚构地下通道检查，包含环境变化和团队决定。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Our spare lights ready, we entered the first chamber. Water soon covered the lower steps. We returned before the rising level blocked the exit.</p><p>独立结构说明准备状态，后两句给出观察和及时调整。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-042">回看本课</a></p><h2 id="lesson-43-·-provided-that-与-unless" tabindex="-1">Lesson 43 · provided that 与 unless <a class="header-anchor" href="#lesson-43-·-provided-that-与-unless" aria-label="Permalink to &quot;Lesson 43 · provided that 与 unless {#lesson-43-·-provided-that-与-unless}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> In this fictional scheme, repairs are covered provided that the damage is reported within a week.</p><h3 id="练习-1-42" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-42" aria-label="Permalink to &quot;练习 1 {#练习-1-42}&quot;">​</a></h3><p>虚构规则允许两周后首次报告吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不允许据此获得所述保障。</p><p><strong>解析：</strong> 条件明确为一周内报告。</p></details><p><strong>表达迁移：</strong> 为虚构物品借用制度写三句，明确保障、条件和例外。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The club will repair borrowed lamps if faults are reported promptly. Batteries are not included in this promise. Members should photograph the damage before returning a lamp.</p><p>规则结果、例外和操作建议分开，避免把一般说明读成无限承诺。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-043">回看本课</a></p><h2 id="lesson-44-·-平行结构与-not-only" tabindex="-1">Lesson 44 · 平行结构与 not only <a class="header-anchor" href="#lesson-44-·-平行结构与-not-only" aria-label="Permalink to &quot;Lesson 44 · 平行结构与 not only {#lesson-44-·-平行结构与-not-only}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The night train offers both a quiet place to sleep and a direct route to the city centre.</p><h3 id="练习-1-43" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-43" aria-label="Permalink to &quot;练习 1 {#练习-1-43}&quot;">​</a></h3><p>例句 both ... and 连接什么类型成分？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 两个名词短语。</p><p><strong>解析：</strong> a quiet place 与 a direct route 都是 offers 的宾语。</p></details><p><strong>表达迁移：</strong> 比较两种虚构通勤方案，用三句说明总时间和舒适度。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The express bus is faster on the main road. However, the local train takes me directly to the office district. It offers both predictable travel time and a seat where I can read.</p><p>局部速度与全程便利分开比较，两个优点以平行名词短语呈现。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-044">回看本课</a></p><h2 id="lesson-45-·-报告动词及其结构" tabindex="-1">Lesson 45 · 报告动词及其结构 <a class="header-anchor" href="#lesson-45-·-报告动词及其结构" aria-label="Permalink to &quot;Lesson 45 · 报告动词及其结构 {#lesson-45-·-报告动词及其结构}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The reporter stated the figures, while the campaigner claimed that they showed a wider problem.</p><h3 id="练习-1-44" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-44" aria-label="Permalink to &quot;练习 1 {#练习-1-44}&quot;">​</a></h3><p>例句中“更广泛的问题”是谁的判断？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 倡议者的判断。</p><p><strong>解析：</strong> claimed that 明确归属。</p></details><p><strong>表达迁移：</strong> 写三句报道摘要，区分观察、引用和未证实内容。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The newspaper published photographs of the damaged bridge. Residents said that repairs had been delayed. The council has not yet confirmed the proposed reopening date.</p><p>可见材料、居民说法、机构尚未确认分别标注，避免混成一个确定结论。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-045">回看本课</a></p><h2 id="lesson-46-·-过去能力与一次成功" tabindex="-1">Lesson 46 · 过去能力与一次成功 <a class="header-anchor" href="#lesson-46-·-过去能力与一次成功" aria-label="Permalink to &quot;Lesson 46 · 过去能力与一次成功 {#lesson-46-·-过去能力与一次成功}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> After several careful attempts, I managed to remove the damaged screw.</p><h3 id="练习-1-45" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-45" aria-label="Permalink to &quot;练习 1 {#练习-1-45}&quot;">​</a></h3><p>例句螺丝是否最终取出？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 是。</p><p><strong>解析：</strong> managed to 明确实际成功。</p></details><p><strong>表达迁移：</strong> 用三句写一次低风险物品组装经历，说明困难和处理结果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I could assemble simple shelves, but this kit had unclear labels. After sorting the parts by size, I managed to fit the frame together. I left the final wall mounting to an experienced installer.</p><p>一般能力、具体成功和能力边界各自清楚，不把部分成功说成全部完成。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-046">回看本课</a></p><h2 id="lesson-47-·-because、therefore-与因果关系" tabindex="-1">Lesson 47 · because、therefore 与因果关系 <a class="header-anchor" href="#lesson-47-·-because、therefore-与因果关系" aria-label="Permalink to &quot;Lesson 47 · because、therefore 与因果关系 {#lesson-47-·-because、therefore-与因果关系}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The courtyard remained noisy after midnight; therefore, several residents moved their bedrooms to the rear.</p><h3 id="练习-1-46" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-46" aria-label="Permalink to &quot;练习 1 {#练习-1-46}&quot;">​</a></h3><p>例句 therefore 前为何不用普通逗号直接拼接？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 两侧都是完整分句。</p><p><strong>解析：</strong> 连接副词本身不能充当并列连词。</p></details><p><strong>表达迁移：</strong> 用三句评价一个虚构便利设施的代价，列出观察和改进建议。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The new delivery entrance saves workers time. However, metal carts wake nearby residents before dawn. Rubber wheels and later collection hours may reduce the disturbance.</p><p>便利与代价均具体，may 避免对改进效果作未经测试的保证。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-047">回看本课</a></p>',100)])])}const u=s(r,[["render",n]]);export{m as __pageData,u as default};
